        &lt;h2&gt;


        Step 1: Set Up Shared GraphQL Schema
        &lt;/h2&gt;

        &lt;p&gt;
&lt;/p&gt;

        &lt;p&gt;We start with a shared GraphQL schema that works across web, mobile, and server environments. This eliminates schema drift and redundant resolver logic.&lt;/p&gt;

        &lt;p&gt;
&lt;br&gt;
        &lt;/p&gt;

        &lt;div class="highlight js-code-highlight"&gt;
        &lt;pre class="highlight javascript"&gt;&lt;code&gt;&lt;span class="c1"&gt;// shared/schema.js
// Shared GraphQL schema for cross-platform React RSC + GraphQL app
// Uses graphql/graphql-js (https://github.com/graphql/graphql-js) v16.8.1
import {
  GraphQLSchema,
  GraphQLObjectType,
  GraphQLString,
  GraphQLInt,
  GraphQLFloat,
  GraphQLList,
  GraphQLError,
  GraphQLNonNull,
} from 'graphql';

// Custom error class for consistent error handling across platforms
class ProductNotFoundError extends GraphQLError {
  constructor(productId) {
    super(`Product with ID ${productId} not found`);
    this.extensions = {
      code: 'PRODUCT_NOT_FOUND',
      productId,
      timestamp: new Date().toISOString(),
    };
  }
}

// Mock product data store (replace with database in production)
const mockProducts = [
  { id: '1', name: 'Wireless Headphones', price: 129.99, stock: 42, category: 'electronics' },
  { id: '2', name: 'Organic Cotton T-Shirt', price: 24.99, stock: 156, category: 'apparel' },
  { id: '3', name: 'Stainless Steel Water Bottle', price: 34.99, stock: 89, category: 'home' },
];

// Define Product GraphQL type with non-null constraints for required fields
const ProductType = new GraphQLObjectType({
  name: 'Product',
  description: 'E-commerce product with inventory data',
  fields: () =&amp;gt; ({
    id: { type: new GraphQLNonNull(GraphQLString), description: 'Unique product identifier' },
    name: { type: new GraphQLNonNull(GraphQLString), description: 'Display name of product' },
    price: { type: new GraphQLNonNull(GraphQLFloat), description: 'Retail price in USD' },
    stock: { type: new GraphQLNonNull(GraphQLInt), description: 'Current inventory count' },
    category: { type: new GraphQLNonNull(GraphQLString), description: 'Product category for filtering' },
  }),
});

// Root Query type with error-handling resolver logic
const RootQueryType = new GraphQLObjectType({
  name: 'Query',
  description: 'Root query type for product data',
  fields: () =&amp;gt; ({
    products: {
      type: new GraphQLNonNull(new GraphQLList(new GraphQLNonNull(ProductType))),
      description: 'Fetch all products, optionally filtered by category',
      args: {
        category: { type: GraphQLString, description: 'Optional category to filter products' },
      },
      resolve: (parent, args) =&amp;gt; {
        try {
          if (args.category) {
            const filtered = mockProducts.filter(p =&amp;gt; p.category === args.category);
            if (filtered.length === 0) {
              throw new GraphQLError(`No products found for category: ${args.category}`, {
                extensions: { code: 'CATEGORY_EMPTY', category: args.category },
              });
            }
            return filtered;
          }
          return mockProducts;
        } catch (err) {
          // Re-throw GraphQL errors directly, wrap others in generic error
          if (err instanceof GraphQLError) throw err;
          throw new GraphQLError('Failed to fetch products', {
            extensions: { code: 'FETCH_ERROR', originalError: err.message },
          });
        }
      },
    },
    product: {
      type: ProductType,
      description: 'Fetch single product by ID',
      args: {
        id: { type: new GraphQLNonNull(GraphQLString), description: 'Product ID to fetch' },
      },
      resolve: (parent, args) =&amp;gt; {
        try {
          const product = mockProducts.find(p =&amp;gt; p.id === args.id);
          if (!product) throw new ProductNotFoundError(args.id);
          return product;
        } catch (err) {
          if (err instanceof GraphQLError) throw err;
          throw new GraphQLError('Failed to fetch product', {
            extensions: { code: 'FETCH_ERROR', originalError: err.message },
          });
        }
      },
    },
  }),
});

// Export final schema for use in RSC server, Expo client, and Next.js API routes
export const schema = new GraphQLSchema({
  query: RootQueryType,
  // Mutation type omitted for brevity, add in production
});

// Validate schema on startup (only runs in Node.js environments)
if (typeof process !== 'undefined' &amp;amp;&amp;amp; process.env.NODE_ENV !== 'test') {
  try {
    // Schema validation ensures no missing required fields
    const { validateSchema } = require('graphql');
    const errors = validateSchema(schema);
    if (errors.length &amp;gt; 0) {
      console.error('Schema validation failed:', errors);
      process.exit(1);
    }
    console.log('✅ Shared GraphQL schema validated successfully');
  } catch (err) {
    console.error('Schema validation error:', err);
  }
}
&lt;/span&gt;
        &lt;/code&gt;&lt;/pre&gt;

        &lt;/div&gt;



        &lt;p&gt;
&lt;/p&gt;

        &lt;p&gt;&lt;strong&gt;Troubleshooting Tip:&lt;/strong&gt; If you see schema validation errors, check that all non-null fields in your type definitions have corresponding resolver returns. Missing fields in mock data will throw validation errors in Node.js environments.&lt;/p&gt;

        &lt;p&gt;
&lt;/p&gt;

        &lt;p&gt;

&lt;/p&gt;

        &lt;p&gt;
&lt;/p&gt;

        &lt;h2&gt;


        Step 2: React Server Components for Web (Next.js)
        &lt;/h2&gt;

        &lt;p&gt;
&lt;/p&gt;

        &lt;p&gt;Next.js 14+ enables RSC by default. We’ll build a server-rendered product listing page that fetches GraphQL data directly on the server, with no client-side JavaScript for initial load.&lt;/p&gt;

        &lt;p&gt;
&lt;br&gt;
        &lt;/p&gt;

        &lt;div class="highlight js-code-highlight"&gt;
        &lt;pre class="highlight jsx"&gt;&lt;code&gt;&lt;span class="c1"&gt;// app/products/page.jsx
// React Server Component (RSC) for product listing page
// Uses Next.js 14.2.3 (https://github.com/vercel/next.js) with RSC enabled by default
import { graphql } from 'graphql';
import { schema } from '../../shared/schema';
import ProductCard from './ProductCard';
import ErrorBoundary from './ErrorBoundary';

// GraphQL query for product listing (executed server-side in RSC)
const PRODUCTS_QUERY = `
  query GetProducts($category: String) {
    products(category: $category) {
      id
      name
      price
      stock
      category
    }
  }
`;

// Server-side data fetching function (runs in RSC context, no client JS)
async function fetchProducts(category = null) {
  try {
    // Execute GraphQL query directly against shared schema in server context
    const result = await graphql({
      schema,
      source: PRODUCTS_QUERY,
      variableValues: { category },
      // Context for future auth/database integration
      contextValue: { user: null, db: null },
    });

    if (result.errors) {
      // Throw first GraphQL error for error boundary to catch
      throw new Error(result.errors[0].message, { cause: result.errors });
    }

    return result.data.products;
  } catch (err) {
    // Log server-side error for observability (use Sentry/DataDog in production)
    console.error('[RSC Product Fetch] Failed to fetch products:', err);
    throw new Error(`Failed to load products: ${err.message}`, { cause: err });
  }
}

// RSC default export (server-rendered, no client-side JS for initial load)
export default async function ProductsPage({ searchParams }) {
  // Extract category filter from URL search params (server-side)
  const category = searchParams?.category || null;
  let products = [];
  let error = null;

  try {
    products = await fetchProducts(category);
  } catch (err) {
    error = err;
  }

  return (


        Product Catalog
        {category &amp;amp;&amp;amp; (Filtered: {category})}


      {/* Category filter links (server-rendered, no client JS) */}


          All


          Electronics


          Apparel


          Home



      {/* Error boundary for graceful failure */}
      Failed to load products. Please try again.}&amp;gt;
        {error ? (
          Error: {error.message}
        ) : (

            {products.map(product =&amp;gt; (

            ))}

        )}


  );
}

// Generate static params for ISR (Incremental Static Regeneration) if needed
export async function generateStaticParams() {
  return ['electronics', 'apparel', 'home'].map(category =&amp;gt; ({ category }));
}

// Set revalidation period for ISR (60 seconds)
export const revalidate = 60;
&lt;/span&gt;
        &lt;/code&gt;&lt;/pre&gt;

        &lt;/div&gt;



        &lt;p&gt;
&lt;/p&gt;

        &lt;p&gt;&lt;strong&gt;Troubleshooting Tip:&lt;/strong&gt; If you see "window is not defined" errors, ensure you’re not importing client-side libraries (like Apollo Client) in RSC. RSC cannot access browser APIs. Use the 'use client' directive only for interactive client components.&lt;/p&gt;

        &lt;p&gt;
&lt;/p&gt;

        &lt;p&gt;

&lt;/p&gt;

        &lt;p&gt;
&lt;/p&gt;

        &lt;h2&gt;


        Step 3: Cross-Platform GraphQL Client for Expo
        &lt;/h2&gt;

        &lt;p&gt;
&lt;/p&gt;

        &lt;p&gt;We’ll build a shared GraphQL client that works for Expo (iOS/Android) and Next.js client components, with retry logic and error normalization.&lt;/p&gt;

        &lt;p&gt;
&lt;br&gt;
        &lt;/p&gt;

        &lt;div class="highlight js-code-highlight"&gt;
        &lt;pre class="highlight javascript"&gt;&lt;code&gt;&lt;span class="c1"&gt;// shared/graphql-client.js
// Cross-platform GraphQL client for Expo (iOS/Android) and Next.js client components
// Uses graphql-request v6.1.0 (https://github.com/prisma/graphql-request) for lightweight fetching
import { GraphQLClient } from 'graphql-request';
import { ProductNotFoundError } from './errors';

// Environment-specific GraphQL endpoint (configured via expo-constants for mobile)
const getGraphQLEndpoint = () =&amp;gt; {
  if (typeof window !== 'undefined') {
    // Web client: use relative API route
    return '/api/graphql';
  }
  // Expo mobile: use environment variable or fallback to local dev server
  const { Constants } = require('expo-constants');
  return Constants.manifest?.extra?.graphqlEndpoint || 'http://localhost:3000/api/graphql';
};

// Initialize client with error handling and retry logic
class CrossPlatformGraphQLClient {
  constructor() {
    this.client = new GraphQLClient(getGraphQLEndpoint(), {
      headers: {
        'Content-Type': 'application/json',
      },
      // Retry failed requests (max 2 retries for network errors)
      fetch: this.retryFetch.bind(this),
    });
  }

  // Retry logic for transient network failures
  async retryFetch(url, options, retries = 2) {
    try {
      const response = await fetch(url, options);
      if (!response.ok) {
        throw new Error(`HTTP ${response.status}: ${response.statusText}`);
      }
      return response;
    } catch (err) {
      if (retries &amp;lt;= 0) throw err;
      console.warn(`Retrying GraphQL request (${retries} left):`, err.message);
      await new Promise(resolve =&amp;gt; setTimeout(resolve, 1000 * (3 - retries))); // Exponential backoff
      return this.retryFetch(url, options, retries - 1);
    }
  }

  // Generic request method with error normalization
  async request(query, variables = {}) {
    try {
      const data = await this.client.request(query, variables);
      return { data, error: null };
    } catch (err) {
      // Normalize GraphQL errors to consistent format
      const normalizedError = this.normalizeError(err);
      console.error('[GraphQL Client] Request failed:', normalizedError);
      return { data: null, error: normalizedError };
    }
  }

  // Normalize errors across platforms (web, iOS, Android)
  normalizeError(err) {
    if (err.response?.errors) {
      // GraphQL errors from server
      const firstError = err.response.errors[0];
      return {
        message: firstError.message,
        code: firstError.extensions?.code || 'GRAPHQL_ERROR',
        originalError: firstError,
      };
    }
    if (err instanceof ProductNotFoundError) {
      return {
        message: err.message,
        code: 'PRODUCT_NOT_FOUND',
        originalError: err,
      };
    }
    // Network or unknown errors
    return {
      message: err.message || 'Unknown error occurred',
      code: 'NETWORK_ERROR',
      originalError: err,
    };
  }
}

// Export singleton instance for shared use across platforms
export const graphqlClient = new CrossPlatformGraphQLClient();

// Example query for product details (used in both web client components and Expo screens)
export const PRODUCT_DETAIL_QUERY = `
  query GetProduct($id: String!) {
    product(id: $id) {
      id
      name
      price
      stock
      category
    }
  }
`;

// Helper function to fetch product details with error handling
export async function fetchProductDetails(productId) {
  const { data, error } = await graphqlClient.request(PRODUCT_DETAIL_QUERY, { id: productId });
  if (error) throw new Error(error.message, { cause: error });
  if (!data.product) throw new ProductNotFoundError(productId);
  return data.product;
}
&lt;/span&gt;
        &lt;/code&gt;&lt;/pre&gt;

        &lt;/div&gt;



        &lt;p&gt;
&lt;/p&gt;

        &lt;p&gt;&lt;strong&gt;Troubleshooting Tip:&lt;/strong&gt; For Expo mobile, ensure your GraphQL endpoint is accessible from physical devices by using your local IP address (e.g., &lt;a href="http://192.168.1.100:3000/api/graphql" rel="noopener noreferrer"&gt;http://192.168.1.100:3000/api/graphql&lt;/a&gt;) instead of localhost during development.&lt;/p&gt;

